import re

TILES = [
    (14,19,20,25),(14,19,28,33),(14,19,36,41),
    (22,27,20,25),(22,27,28,33),(22,27,36,41),
    (30,35,20,25),(30,35,28,33),(30,35,36,41),
    (46,51,20,25),(46,51,28,33),(46,51,36,41),
]

# Global palette rotation: collapse dark/neutral colours to charcoal 'c'
REMAP = {'B':'c', 'b':'c', 'R':'c', 'G':'c', 'g':'c', 'W':'c'}

def _col_band(col):
    if 20 <= col <= 25: return 0
    if 28 <= col <= 33: return 1
    if 36 <= col <= 41: return 2
    return None

def _row_off(row):
    if 14 <= row <= 19: return 0
    if 22 <= row <= 27: return 1
    if 30 <= row <= 35: return 1
    if 46 <= row <= 51: return 2
    return None

def predict(board_lines, action):
    b = [list(row) for row in board_lines]
    m = re.match(r'MOUSE\(row=(\d+),\s*col=(\d+)\)', action)
    if not m:
        return [''.join(r) for r in b]
    r, c = int(m.group(1)), int(m.group(2))

    tile = None
    for (rt, rb, cl, cr) in TILES:
        if rt <= r <= rb and cl <= c <= cr:
            tile = (rt, rb, cl, cr); break

    if tile is not None:
        rt, rb, cl, cr = tile
        present = set(b[i][j] for i in range(rt,rb+1) for j in range(cl,cr+1))
        has_b = 'b' in present
        has_O = 'O' in present
        if has_b and not has_O:
            newc = 'O'
        elif has_O and not has_b:
            newc = 'b'
        else:
            newc = 'O'
        for i in range(rt, rb+1):
            for j in range(cl, cr+1):
                if b[i][j] in ('b','O'):
                    b[i][j] = newc
        if newc == 'O':
            cb = _col_band(c); ro = _row_off(r)
            if cb is not None and ro is not None:
                p = 7 - cb - ro
                ca, cc = 2*p-2, 2*p-1
                if 0 <= ca < 64 and 0 <= cc < 64:
                    b[63][ca] = 'Y'; b[63][cc] = 'Y'
    else:
        # global palette rotation
        for i in range(64):
            row = b[i]
            for j in range(64):
                ch = row[j]
                if ch in REMAP:
                    row[j] = REMAP[ch]
    return [''.join(row) for row in b]
